<?php

namespace App\Tailoring;

?>
<h1 class="h3 mb-4"><?= t('Enquiries')?></h1><div class="row g-3"><?php foreach ($enquiries as $enquiry) { ?><div class="col-lg-6"><article class="card h-100"><div class="card-body"><span class="badge text-bg-secondary mb-3"><?= e($enquiry['status'])?></span><h2 class="h5"><?= e($enquiry['name'])?></h2><a href="tel:+91<?= e($enquiry['mobile'])?>"><?= e($enquiry['mobile'])?></a><p class="small mt-3"><?= nl2br(e($enquiry['message']))?></p><p class="small text-secondary"><?= e($enquiry['created_at'])?> UTC</p><?php if ($enquiry['converted_order_id']) { ?><a href="/admin/orders/<?= (int) $enquiry['converted_order_id']?>"><?= t('View order')?></a><?php } else { ?><form method="post" action="/admin/enquiries/<?= (int) $enquiry['id']?>/status" class="d-flex gap-2 mb-3"><?= csrf_field()?><label class="visually-hidden" for="enquiry-<?= (int) $enquiry['id']?>"><?= t('Status')?></label><select class="form-select" id="enquiry-<?= (int) $enquiry['id']?>" name="status"><?php foreach (['NEW', 'CONTACTED', 'CLOSED'] as $s) { ?><option <?= $enquiry['status'] === $s ? 'selected' : ''?>><?= e($s)?></option><?php } ?></select><button class="btn btn-outline-primary"><?= t('Save')?></button></form><form method="post" action="/admin/enquiries/<?= (int) $enquiry['id']?>/convert"><?= csrf_field()?><button class="btn btn-primary"><?= t('Create order from enquiry')?></button></form><?php } ?></div></article></div><?php } ?><?php if (! $enquiries) { ?><p class="text-secondary"><?= t('No enquiries yet.')?></p><?php } ?></div>
